# Generated by build.py from recipe.yml for recipe ftp-mirror-a-folder-with-a-script. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'public', 'public/css', 'public/docs', 'public/docs/2026' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/README.txt'), "mirrors land under /mirror`n")
[IO.File]::WriteAllText((Join-Path $PWD 'public/index.html'), "<h1>home</h1>`n")
[IO.File]::WriteAllText((Join-Path $PWD 'public/css/site.css'), "body { margin: 0 }`n")
[IO.File]::WriteAllText((Join-Path $PWD 'public/docs/guide.txt'), "read me first`n")
[IO.File]::WriteAllText((Join-Path $PWD 'public/docs/2026/notes.txt'), "november`n")
[IO.File]::WriteAllText((Join-Path $PWD 'mirror.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# mirror.sh FOLDER URL: uploads every file under FOLDER to the FTP folder URL (ending in /) in one`n# curl command, making folders as it goes and stopping at the first failure with curl's exit code;`n# then lists each folder on the server. Names with spaces or characters a URL cannot hold are not handled.`nsrc=`$1; url=`$2`nset --`nfor f in `$(cd `"`$src`" && find . -type f | sort); do`n  set -- `"`$@`" -T `"`$src/`${f#./}`" `"`$url`${f#./}`"`ndone`ncurl -sS --ftp-create-dirs --fail-early -w `"put %{url.path} %{exitcode}\n`" `"`$@`" || exit`nfor d in `$(cd `"`$src`" && find . -type d | sort); do`n  d=`${d#.}; d=`${d#/}; d=`${d:+`$d/}`n  echo `"listing ./`$d: `$(curl -sS -l `"`$url`$d`" | tr -d '\r' | sort | tr '\n' ' ')`"`ndone`n")
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--allow-uploads', '--list-directories', '--directory', 'site', 'ftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh mirror.sh public ftp://127.0.0.1:8080/mirror/ } finally { Stop-Process $server0 }
